/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
-    assign B = (A<<8)-(A<<2)+A;
+    assign B = (A<<8)-(A<<2)-A;
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg [7:0] A;
  wire [15:0] B;
  integer i;

  TopModule dut (
    .A(A),
    .B(B)
  );

  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      A = i[7:0];
      #1;
      if (B "'!== (A * 16'"'h00FB)) begin
        "'$display("MISMATCH A=%0d B=%0d expected=%0d", A, B, (A * 16'"'h00FB));
        "'$finish(1);
      end
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

